const root=resolve('assistant-source');
try{await access(root);throw new Error('assistant-source already exists; refusing to overwrite.');}catch(e){if(e.code!=='ENOENT')throw e;}
await mkdir(root);
for(const [name,body] of Object.entries(files)){const target=resolve(root,name);if(!target.startsWith(root+sep))throw new Error('Unsafe source path');await mkdir(dirname(target),{recursive:true});await writeFile(target,body,{flag:'wx'});}
console.log('Extracted '+Object.keys(files).length+' source files into assistant-source. Read README.md there before running.');
